(() => {
'use strict';
const M=window.MechanismCore,D=window.LearningDiagrams;
const oldTeaching=window.processTeaching;
const stages=(where,labels,steps,breaks=[0,.24,.48,.76,1])=>({where,labels,steps,breaks});
function teaching(mode,s){
 if(mode==='application'&&['anaemia','scurvy'].includes(s.application)){const vitamin=s.application==='scurvy';return stages(vitamin?'Vitamin C deficiency → scurvy 維生素 C 缺乏 → 壞血病':'Iron deficiency → anaemia 缺鐵 → 貧血',['Nutrient 營養素','Poor absorption 吸收不良',vitamin?'Collagen 膠原蛋白':'Haemoglobin 血紅蛋白','Over time 長期後果'],[vitamin?'This subtab follows vitamin C from the notes’ deficiency case. 此分頁追蹤原個案中的維生素 C。':'This subtab follows iron from the notes’ deficiency case. 此分頁追蹤原個案中的鐵。','Damaged villi and transport proteins can reduce nutrient absorption. 絨毛及載體蛋白受損可減少營養素吸收。',vitamin?'Vitamin C supports normal collagen formation and connective tissue. 維生素 C 支持正常膠原蛋白形成及結締組織。':'Iron is required to form haemoglobin in developing red blood cells. 發育中的紅血球需要鐵製造血紅蛋白。',vitamin?'Long-term vitamin C deficiency can cause scurvy, with weakened connective tissue and poor healing. 長期缺乏維生素 C 可造成壞血病，令結締組織及傷口癒合受影響。':'Iron deficiency can cause anaemia and reduce oxygen-carrying capacity. 缺鐵可造成貧血，降低攜氧能力。']);}
 if(['anaemia','scurvy'].includes(s.application))s={...s,deficiency:s.application==='scurvy'?'vitaminC':'iron',application:'deficiency'};
 if(mode==='route')return s.route==='lipid'?stages('Lacteal → lymph → venous blood 乳糜管 → 淋巴 → 靜脈血',['Start 起點','Lymph 淋巴','Venous junction 匯入靜脈','Heart 到心臟'],['The ring identifies a lipid package already absorbed into a lacteal. 光圈標示已進入乳糜管的脂質微粒。','Follow the package along lymphatic vessels. 沿淋巴管追蹤脂質微粒。','The thoracic duct joins venous blood near the left subclavian vein. 胸導管在左鎖骨下靜脈附近匯入血液。','Venous blood returns to the right heart, then goes through the lungs before systemic delivery. 靜脈血先回右心，再經肺循環到左心。'],[0,.1,.9,.94,1]):stages('Intestine → liver → venous return 小腸 → 肝 → 靜脈回流',['Gut capillaries 小腸微血管','Portal vein 肝門靜脈','Liver sinusoids 肝血竇','Venous return 靜脈回流'],['Start AFTER absorption into an intestinal capillary. The white ring follows one glucose marker. 此圖由營養素已入小腸微血管開始；白圈追蹤一個葡萄糖標記。','The portal vein carries the marker from the first capillary bed to the second. 肝門靜脈把營養素由第一組微血管帶往第二組。','Portal blood enters liver sinusoids. The hepatic artery also supplies this network. 門靜脈血流入肝血竇；肝動脈亦供血至此。','Blood leaves via hepatic veins and the inferior vena cava, reaching the right heart. 血液經肝靜脈及下腔靜脈回到右心。'],[0,.23,.52,.72,1]);
 if(mode==='villi'){const a=D.adaptations[s.adaptation||'surface'];return stages('Small-intestine wall 小腸壁',['Structure 結構','Cross lining 穿過上皮','Enter vessels 進入管道','Carry away 被帶走'],[a[2]+' '+a[3],'The nutrient crosses a single layer of epithelial cells; carriers are shown at the entry site. 營養素穿過單層上皮，圖中入口標示載體位置。',s.adaptation==='lacteal'?'Long-chain fat is packaged in enterocytes before entering the lacteal. 長鏈脂肪先在上皮細胞內包裝，再入乳糜管。':'Glucose enters a nearby capillary after leaving the epithelial cell. 葡萄糖離開上皮細胞後進入附近微血管。','Blood and lymph carry absorbed nutrients away, helping maintain a concentration gradient. 血流及淋巴帶走營養素，有助維持濃度梯度。']);}
 if(mode==='application'){
  const data={coeliac:['Coeliac disease 乳糜瀉',['Healthy surface 正常表面','Immune damage 免疫損傷','Reduced uptake 吸收減少','Consequence 後果'],['Compare the same number of villi and nutrient markers. 比較相同數目的絨毛及營養素標記。','In susceptible people, gluten triggers immune-mediated damage; gluten does not scrape villi flat. 在患者中，麩質引發免疫反應而損害絨毛，並非直接刮平絨毛。','Flattened villi have less surface area. More markers remain in the lumen. 絨毛扁平後面積減少，較多營養素留在腸腔。','Poor absorption can cause deficiency; retained solutes reduce water absorption and may cause diarrhoea. 吸收不良可造成營養缺乏；溶質留在腸腔令吸水減少，可引致腹瀉。']],lactose:['Brush border + intestinal lumen 刷狀緣及腸腔',['Lactose arrives 乳糖到達','Lactase 乳糖酶','Absorb or retain 吸收或留在腸內','Water & symptoms 水分與症狀'],['Lactose is two linked sugar units. Compare normal lactase with insufficient lactase. 乳糖由兩個糖單位組成；可切換正常及乳糖酶不足。','Lactase at the brush border splits lactose into glucose and galactose. 刷狀緣的乳糖酶把乳糖分成葡萄糖及半乳糖。','Monosaccharides can cross the epithelium. Undigested lactose remains in the lumen. 單糖可穿過上皮；未消化乳糖留在腸腔。','Retained solute retains water. In the colon, bacteria can produce gas and extra fluid. 溶質令水留在腸內；結腸細菌可產生氣體及增加液體。']],cirrhosis:['Functional tissue and bile output 肝組織及膽汁',['Liver tissue 肝組織','Scarring 疤痕','Reduced function 功能減少','Source question 原題'],['Compare functioning liver tissue with cirrhosis. 比較正常功能組織及肝硬化。','Scar tissue replaces functioning tissue over time. 疤痕組織隨時間取代有功能的組織。','Reduced liver function can reduce bile output. 肝功能受損可令膽汁製造減少。','The notes also associate cirrhosis with anaemia; see the original question and supplied answer. 筆記亦將肝硬化與貧血聯繫；請對照原題及答案。']],pancreatic:['Pancreatic duct → duodenum 胰管 → 十二指腸',['Secretion 分泌','Duct transport 胰管運輸','Obstruction or arrival 阻塞或到達','Digestion 消化'],['Pancreatic juice contains digestive enzymes. 胰液含有消化酶。','Enzymes normally reach the duodenum through the pancreatic duct. 消化酶正常會經胰管到十二指腸。','With a blocked duct, enzymes stop before the blockage. 胰管阻塞時，消化酶不能通過阻塞位置。','Less lipase reaches food, so less fat is digested and more fat can appear in faeces. 較少脂肪酶到達食物，脂肪消化減少，糞便脂肪可增加。']],deficiency:['Nutrient uptake and consequences 營養吸收及後果',['Nutrient 營養素','Poor uptake 吸收不良','Cell function 細胞功能','Deficiency 缺乏'],['Choose iron or vitamin C from the controls. 選擇鐵或維生素 C。','Damaged villi or carriers can reduce absorption. 絨毛或載體受損可令吸收減少。','Iron supports haemoglobin formation; vitamin C supports normal collagen. 鐵用作製造血紅蛋白；維生素 C 支持正常膠原蛋白。','Over time, deficiency may cause anaemia or scurvy in the notes’ case study. 原個案中，長期缺乏可導致貧血或壞血病。']],processes:['Across a membrane 經過膜',['Compare sides 比較兩側','Membrane 膜','Net movement 淨移動','Result 結果'],['Choose diffusion, osmosis or active transport. 選擇擴散、滲透或主動運輸。','The membrane and transfer site are drawn explicitly. 圖中清楚標示膜及物質通過的位置。','Diffusion follows a concentration gradient; osmosis concerns water potential; active transport uses energy. 擴散沿濃度梯度；滲透涉及水勢；主動運輸需能量。','Highlighted markers show net movement; actual particles also move randomly. 高亮標記示意淨移動；真實粒子亦有隨機運動。']],experiments:['Experimental models 實驗模型',['Set up 設置','Process 過程','Compare 比較','Explain 解釋'],['Choose lipase, dialysis tubing or microscopy. 選擇脂肪酶、透析管或顯微鏡。','Watch the actual material change or membrane crossing. 觀察實際物質變化或穿過膜。','Compare with a suitable control and keep other variables constant. 配合適當對照，保持其他變量相同。','Use the notes’ original graphs, conditions and marking points for the examination question. 作答時對照筆記原圖、實驗條件及評分點。']]};
  const a=data[s.application]||data.coeliac;return stages(a[0],a[1],a[2],s.application==='coeliac'?[0,.24,.65,.85,1]:undefined);
 }
 if(mode==='glucose'||mode==='liver'&&+s.function===0){if(s.situation==='protein')return teaching('fates',{...s,nutrient:'Amino acids 氨基酸',fate:'excess'});const f=s.situation==='fasting';return stages('Liver sinusoid → tissue fluid → liver cell 肝血竇 → 組織液 → 肝細胞',['Trigger 血糖改變','Hormone signal 激素訊息','Exchange + reaction 運輸及反應','Blood restored 血糖回復'],[f?'During fasting, blood glucose falls. 空腹時血糖下降。':'After a carbohydrate meal, blood glucose rises. 進食碳水化合物後血糖上升。',f?'Glucagon travels in blood, leaves through the sinusoid wall and binds to a receptor OUTSIDE the liver cell. 升糖素經血液及血竇壁到達肝細胞外，與受體結合。':'Insulin travels in blood, leaves through the sinusoid wall and binds to a receptor OUTSIDE the liver cell. 胰島素經血液及血竇壁到達肝細胞外，與受體結合。',f?'The signal promotes glycogen breakdown. Glucose crosses a carrier, tissue fluid and the sinusoid wall to enter blood. 訊息促進糖原分解；葡萄糖經載體、組織液及血竇壁進入血液。':'The signal favours glycogen synthesis. Glucose crosses the sinusoid wall and tissue fluid, then a carrier into the cell. 訊息促進糖原合成；葡萄糖經血竇壁、組織液及載體進入細胞。',f?'Liver glycogen decreases while blood glucose rises towards normal. 肝糖原減少，血糖回升至正常。':'Liver glycogen increases while blood glucose falls towards normal. 肝糖原增加，血糖回落至正常。'],[0,.18,.4,.8,1]);}
 if(mode==='fates'||mode==='liver'&&+s.function===3){const kind=mode==='liver'?'deamination':M.fateKind(s),aa=['protein','deamination'].includes(kind);const outcome={protein:'The SAME amino-acid units become a joined protein chain. 同一批氨基酸單位連接成蛋白質鏈。',glycogen:'The SAME glucose units join a branched glycogen store inside the cell. 同一批葡萄糖單位在細胞內連接成分支糖原。',energy:'Respiration uses glucose and oxygen, releases energy and forms carbon dioxide and water. 呼吸作用利用葡萄糖及氧，釋放能量並產生二氧化碳及水。',fat:'Cell reactions convert or reassemble materials into stored lipids. 細胞內反應將物質轉換或重組成儲存脂質。',membrane:'Lipid components are used to build membrane phospholipids. 脂質成分被用作製造細胞膜磷脂。',hormone:'A lipid precursor such as cholesterol is used to make steroid sex hormones. 膽固醇等脂質前體被用作製造類固醇性激素。',deamination:'The nitrogenous part is removed and forms urea through several reactions. The carbon portion remains available. 含氮部分被移除並經多個反應形成尿素；其餘碳骨架可再利用。'};
  return stages(['glycogen','deamination'].includes(kind)?'Inside liver cells 肝細胞內':kind==='fat'?'Inside liver or fat cells 肝／脂肪細胞內':'Inside a body cell 身體細胞內',['Blood 血液','Exchange 穿過邊界','Cell reaction 細胞內反應','Result 結果'],[aa?'Amino acids are carried in blood; the squares identify the selected units. 氨基酸隨血液運輸；方形標記選定的氨基酸單位。':'Follow the selected nutrient markers; the red blood cells remain inside the vessel. 追蹤選定營養素；紅血球一直留在血管內。','Material crosses the vessel wall, moves through tissue fluid, then crosses the cell membrane at the drawn transfer site. 物質經血管壁、組織液，再從圖示的轉運位置穿過細胞膜。',outcome[kind],kind==='deamination'?'Urea leaves through membrane transfer and returns to blood; kidneys later excrete it. 尿素經細胞膜及血管壁回到血液，之後由腎排出。':kind==='hormone'?'Hormone products leave the cell through the indicated route and enter blood. 激素產物經標示路徑離開細胞並進入血液。':'The outcome stays visible. Use the timeline to compare before and after. 結果會保留，可用進度條比較前後。']);
 }
 if(mode==='liver'&&+s.function===2&&s.production!=='carotene')return stages('Liver → gall bladder → duodenum 肝 → 膽囊 → 十二指腸',['Make bile 製造膽汁','Store 儲存','Release 釋放','Emulsify 乳化'],['Liver cells secrete bile into bile ducts. 肝細胞將膽汁分泌到膽管。','The same markers collect in the gall bladder. 同一批標記流入膽囊儲存。','The gall bladder contracts and bile travels through the common bile duct to the duodenum. 膽囊收縮，膽汁經總膽管到十二指腸。','A large fat droplet becomes smaller droplets. Bile does not chemically digest triglycerides. 大油滴分成小油滴；膽汁不會化學消化甘油三酯。'],[0,.25,.55,.83,1]);
 const a=oldTeaching(mode,s);return stages(a.where,[...a.labels.slice(0,2),'Cell reaction 細胞內反應',a.labels[2]],[a.steps[0],'Follow the explicitly drawn compartments. 依照圖中的細胞及管道邊界觀察。',a.steps[1],a.steps[2]]);
}
function render(mode,s){if(['anaemia','scurvy'].includes(s.application))s={...s,deficiency:s.application==='scurvy'?'vitaminC':'iron',application:'deficiency'};const t=M.clamp(s.phase||0);let body;
 if(mode==='villi')body=D.villi(s,t);else if(mode==='route')body=D.route(s,t);else if(mode==='application')body=D.application(s,t);else if(mode==='fates')body=M.assimilation(s,t);else if(mode==='glucose')body=M.regulation(s,t);else if(mode==='liver')body=+s.function===0?M.regulation(s,t):+s.function===1?M.stores(s,t):+s.function===2?(s.production==='carotene'?M.carotene(s,t):M.bile(s,t)):+s.function===3?M.deamination(s,t):M.detox(s,t);else return '';
 const info=teaching(mode,s);return M.svg(body,info.where,'Follow each named structure and the selected material through the four teaching stages. Compartments and transfers are schematic, not to scale.');
}
class LearningScene{constructor(host){this.host=host;this.key=''}setState(mode,s){const svg=window.learningSceneSVG(mode,s),html=window.presentLearningScene?window.presentLearningScene(mode,s,svg):svg;this.host.innerHTML=`<div class="learning-scene"><div class="learning-scene-actions"><span>2D MECHANISM · 機制動畫</span><button data-expand-learning="true" aria-label="Enlarge the teaching diagram">⛶ Enlarge 放大</button></div>${html}</div>`;const button=this.host.querySelector('[data-expand-learning]'),panel=this.host.closest('.panel');const label=()=>{const expanded=panel.classList.contains('model-expanded');button.textContent=expanded?'↙ Return 返回':'⛶ Enlarge 放大';button.setAttribute('aria-pressed',expanded)};label();button.onclick=()=>{panel.classList.toggle('model-expanded');label()}}}
window.LearningScene=LearningScene;window.learningSceneSVG=render;window.processTeaching=teaching;
})();
